arguments.command:
true_cmd=$(cat << 'EOF_TRUE'
<||then_command||>
EOF_TRUE
) && false_cmd=$(cat << 'EOF_FALSE'
<||else_command||>
EOF_FALSE
) && cond=$(cat << 'EOF_COND'
<||condition||>
EOF_COND
) && true_cmd="${true_cmd//,/;}" && false_cmd="${false_cmd//,/;}" && if termy -y "$cond" >/dev/null 2>&1; then termy -y "$true_cmd"; else if [ -n "$false_cmd" ]; then termy -y "$false_cmd"; fi; fi
